from __future__ import annotations

def fib_pair_mod(n: int, modulus: int) -> tuple[int, int]:
    """Compute (F_n, F_{n+1}) modulo modulus in O(log n) recursion levels."""
    if n < 0 or modulus < 1:
        raise ValueError("require n >= 0 and modulus >= 1")
    if n == 0:
        return 0, 1 % modulus
    a, b = fib_pair_mod(n // 2, modulus)
    even = a * ((2 * b - a) % modulus) % modulus
    odd = (a * a + b * b) % modulus
    return (even, odd) if n % 2 == 0 else (odd, (even + odd) % modulus)


def fibonacci_index(p: int) -> int:
    if p < 1:
        raise ValueError("p must be positive")
    return p - 1 if p % 5 in (1, 4) else p + 1


def wall_sun_sun_remainder(p: int) -> int:
    """Return F_{I(p)} mod p^2; zero is the square-divisibility condition."""
    if p < 2:
        raise ValueError("p must be at least 2")
    return fib_pair_mod(fibonacci_index(p), p * p)[0]

